import numpy as np
from statsmodels.tsa.arima.model import ARIMA

def coverage(phi, n, h, sims, seed):
    hits = 0
    for s in range(sims):
        x = make_ar1(phi, n + h, seed + s)
        res = ARIMA(x[:n], order=(1, 0, 0)).fit()          # phi and sigma2 estimated
        lower, upper = res.get_forecast(h).conf_int(alpha=0.05)[h - 1]
        hits += lower <= x[n + h - 1] <= upper
    return round(hits / sims, 2)

