import numpy as np
from statsmodels.tsa.arima.model import ARIMA
from statsmodels.tsa.stattools import adfuller
from statsmodels.stats.diagnostic import acorr_ljungbox

def fit_and_forecast(x, max_p, max_q, h, n_train):
    x = np.asarray(x, dtype=float)
    if adfuller(x)[1] > 0.05:
        raise ValueError("unit root not rejected: difference first")
    train = x[:n_train]
    best, best_bic, best_res = None, np.inf, None
    for p in range(max_p + 1):
        for q in range(max_q + 1):
            res = ARIMA(train, order=(p, 0, q)).fit()
            if res.bic < best_bic:
                best, best_bic, best_res = (p, q), res.bic, res
    p, q = best
    lb_p = acorr_ljungbox(best_res.resid, lags=[10], model_df=p + q)["lb_pvalue"].iloc[0]
    full = best_res.apply(x)                       # trained parameters, every day filtered
    pred = full.fittedvalues[n_train:]
    mse = np.mean((x[n_train:] - pred) ** 2)
    lower, upper = full.get_forecast(h).conf_int(alpha=0.05)[h - 1]
    return {"order": best, "lb_p": round(float(lb_p), 3), "mse": round(float(mse), 3),
            "interval": (round(float(lower), 3), round(float(upper), 3))}
